import subprocess, sys, time, os, signal, shutil

def one_round(run):
    """Start server for `run` (run%5 asset is poisoned), try fetches until success."""
    if os.path.exists('.server_ready'):
        os.remove('.server_ready')
    p = subprocess.Popen(['python3', 'scripts/dev_server.py', str(run)])
    for _ in range(40):
        if os.path.exists('.server_ready'):
            break
        time.sleep(0.05)
    port = open('.server_ready').read().strip()
    sys.path.insert(0, 'src')
    from pack import fetch
    results = {}
    for name in ['app.css', 'app.js', 'index.html', 'logo.svg', 'vendor.js']:
        tries = 0
        while True:
            tries += 1
            try:
                fetch(port, name, retries=1)
                results[name] = tries
                break
            except Exception:
                if tries > 60:
                    results[name] = 'FAILED'
                    break
    p.kill()
    p.wait()
    os.remove('.server_ready')
    return results

for run in range(5):
    print('run', run, one_round(run))
EOF

